/// The NERDC national scheme of work, BAKED INTO THE APP (founder
/// directive 2026-10-05): "just add the scheme of work of all subjects
/// to the dart code directly, no need for fetching it, it should just
/// be on the app itself."
///
/// The whole corpus - Nursery 1 to SSS 3, every subject, every term -
/// ships as `assets/nerdc_schemes.json` (generated by
/// scripts/bake_mobile_schemes.py from data/school-schemes/nerdc-2025
/// and committed with the app). The loader below reads that asset
/// straight off the device: zero network, zero database, works in
/// airplane mode and opens instantly.
///
/// The syllabus tab uses this as the national fallback for a class +
/// subject the school has not written its own terms for yet - the same
/// behaviour as the web portal's national bank.
library;

import 'dart:convert' show jsonDecode;

import 'package:flutter/services.dart' show rootBundle;

/// One week of a national scheme of work.
class NerdcWeek {
  const NerdcWeek({required this.week, required this.topic, required this.content});

  final int week;
  final String topic;
  final String content;
}

/// One term's scheme of work for a subject.
class NerdcTermScheme {
  const NerdcTermScheme({required this.term, required this.weeks});

  final int term;
  final List<NerdcWeek> weeks;
}

/// One subject of a class level.
class NerdcSubject {
  const NerdcSubject({required this.id, required this.name, required this.terms});

  final String id;
  final String name;
  final List<NerdcTermScheme> terms;

  NerdcTermScheme? term(int t) =>
      terms.where((NerdcTermScheme x) => x.term == t).firstOrNull;
}

/// One class level (Nursery 1 ... SSS 3).
class NerdcClass {
  const NerdcClass({required this.id, required this.name, required this.subjects});

  final String id;
  final String name;
  final List<NerdcSubject> subjects;
}

/// The loaded national scheme corpus.
class NerdcSchemes {
  const NerdcSchemes({required this.classes});

  final List<NerdcClass> classes;

  static NerdcSchemes? _cache;
  static Future<NerdcSchemes>? _loading;

  /// Loads the bundled asset once per process; every later call returns
  /// the same instance immediately (the future is cached too, so
  /// concurrent first calls share one decode).
  static Future<NerdcSchemes> load() {
    final NerdcSchemes? cached = _cache;
    if (cached != null) return Future<NerdcSchemes>.value(cached);
    return _loading ??= _decode();
  }

  static Future<NerdcSchemes> _decode() async {
    final String raw = await rootBundle.loadString('assets/nerdc_schemes.json');
    // jsonDecode of a 1.2 MB document on the UI isolate takes a few
    // tens of milliseconds - fine for a one-shot tab-open load.
    final dynamic doc = jsonDecode(raw);
    final List<NerdcClass> classes = <NerdcClass>[
      for (final dynamic c in (doc['c'] as List<dynamic>))
        NerdcClass(
          id: (c['id'] ?? '') as String,
          name: (c['n'] ?? '') as String,
          subjects: <NerdcSubject>[
            for (final dynamic s in (c['s'] as List<dynamic>))
              NerdcSubject(
                id: (s['id'] ?? '') as String,
                name: (s['n'] ?? '') as String,
                terms: <NerdcTermScheme>[
                  for (final dynamic t in (s['t'] as List<dynamic>))
                    NerdcTermScheme(
                      term: ((t['t'] ?? 1) as num).toInt(),
                      weeks: <NerdcWeek>[
                        for (final dynamic w in (t['w'] as List<dynamic>))
                          NerdcWeek(
                            week: ((w['w'] ?? 0) as num).toInt(),
                            topic: (w['t'] ?? '') as String,
                            content: (w['c'] ?? '') as String,
                          ),
                      ],
                    ),
                ],
              ),
          ],
        ),
    ];
    final NerdcSchemes value = NerdcSchemes(classes: classes);
    _cache = value;
    _loading = null;
    return value;
  }

  /// Slug of a name - the same normaliser the web portal uses to match
  /// a school's class/subject names onto the national corpus
  /// (lowercase, letters and digits only).
  static String slug(String s) =>
      s.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '');

  /// Finds a national class by slug-matching its id or name against
  /// the school's class name ("JSS 1A", "Primary 4", ...).
  NerdcClass? classForSchoolName(String schoolClassName) {
    final String want = slug(schoolClassName);
    if (want.isEmpty) return null;
    for (final NerdcClass c in classes) {
      if (slug(c.id) == want || slug(c.name) == want) return c;
    }
    // Prefix fall-back: "Primary 4A" -> "Primary 4"; "SSS 1 Gold" -> "SSS 1".
    for (final NerdcClass c in classes) {
      final String cid = slug(c.id);
      final String cname = slug(c.name);
      if ((cid.isNotEmpty && want.startsWith(cid)) ||
          (cname.isNotEmpty && want.startsWith(cname))) {
        return c;
      }
    }
    return null;
  }

  /// Finds a subject of [cls] by slug-matching ("Mathematics",
  /// "BASIC SCIENCE", "maths-studies"...).
  NerdcSubject? subjectForSchoolName(NerdcClass cls, String schoolSubjectName) {
    final String want = slug(schoolSubjectName);
    if (want.isEmpty) return null;
    for (final NerdcSubject s in cls.subjects) {
      if (slug(s.id) == want || slug(s.name) == want) return s;
    }
    for (final NerdcSubject s in cls.subjects) {
      final String sid = slug(s.id);
      if (sid.isNotEmpty && (want.startsWith(sid) || sid.startsWith(want))) {
        return s;
      }
    }
    return null;
  }
}
